CREATE TABLE IF NOT EXISTS public.subcontrato_avances (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subcontrato_id BIGINT NOT NULL, subcontrato_nombre TEXT NOT NULL, empresa TEXT NOT NULL, obra_nombre TEXT NOT NULL, fecha DATE NOT NULL, partida_nombre TEXT NOT NULL, cantidad NUMERIC NOT NULL CHECK(cantidad>=0), unidad TEXT, comentario TEXT, estado TEXT NOT NULL DEFAULT 'Reportado', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subcontrato_asistencia (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subcontrato_id BIGINT NOT NULL, subcontrato_nombre TEXT NOT NULL, empresa TEXT NOT NULL, obra_nombre TEXT NOT NULL, fecha DATE NOT NULL, presentes INTEGER NOT NULL CHECK(presentes>=0), ausentes INTEGER DEFAULT 0 CHECK(ausentes>=0), horas_hombre NUMERIC DEFAULT 0 CHECK(horas_hombre>=0), estado TEXT NOT NULL DEFAULT 'Reportado', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subcontrato_estados_pago (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subcontrato_id BIGINT NOT NULL, subcontrato_nombre TEXT NOT NULL, empresa TEXT NOT NULL, obra_nombre TEXT NOT NULL, numero INTEGER NOT NULL, periodo_desde DATE NOT NULL, periodo_hasta DATE NOT NULL, monto_presentado NUMERIC NOT NULL CHECK(monto_presentado>=0), monto_aprobado NUMERIC, factura_folio TEXT, factura_url TEXT, observaciones TEXT, estado TEXT NOT NULL DEFAULT 'Presentado', aprobado_por TEXT, aprobado_at TIMESTAMPTZ, costo_real_id BIGINT, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(subcontrato_id,obra_nombre,numero));
CREATE TABLE IF NOT EXISTS public.costos_reales_obra (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, obra_nombre TEXT NOT NULL, nombre TEXT NOT NULL, tipo_costo TEXT, asociar_factura BOOLEAN DEFAULT false, num_factura TEXT, monto NUMERIC NOT NULL DEFAULT 0, imputaciones JSONB DEFAULT '[]', empresa TEXT, origen TEXT, origen_id BIGINT UNIQUE, created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE public.subcontrato_avances ENABLE ROW LEVEL SECURITY; ALTER TABLE public.subcontrato_asistencia ENABLE ROW LEVEL SECURITY; ALTER TABLE public.subcontrato_estados_pago ENABLE ROW LEVEL SECURITY; ALTER TABLE public.costos_reales_obra ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['subcontrato_avances','subcontrato_asistencia','subcontrato_estados_pago','costos_reales_obra'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I','empresa_interna_select',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=auth.uid() AND (u.empresa=%I.empresa OR lower(u.empresa)=''obraxis'')))','empresa_interna_select',t,t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(p_estado_pago_id BIGINT,p_aprobado_por TEXT) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ep public.subcontrato_estados_pago; cid BIGINT; BEGIN SELECT * INTO ep FROM public.subcontrato_estados_pago WHERE id=p_estado_pago_id FOR UPDATE; IF ep.id IS NULL THEN RAISE EXCEPTION 'Estado de pago no encontrado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=auth.uid() AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin') OR lower(coalesce(u.rol,'')) LIKE '%admin%' OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.aprobar_pago')) THEN RAISE EXCEPTION 'Tu rol no tiene permiso para aprobar estados de pago de subcontratos'; END IF; IF coalesce(ep.factura_folio,'')='' THEN RAISE EXCEPTION 'Debe existir una factura asociada'; END IF; INSERT INTO public.costos_reales_obra(obra_nombre,nombre,tipo_costo,asociar_factura,num_factura,monto,empresa,origen,origen_id) VALUES(ep.obra_nombre,'Estado de pago subcontrato Â· '||ep.subcontrato_nombre,'Subcontrato',true,ep.factura_folio,coalesce(ep.monto_aprobado,ep.monto_presentado),ep.empresa,'Estado de pago subcontrato',ep.id) ON CONFLICT(origen_id) DO UPDATE SET monto=excluded.monto,num_factura=excluded.num_factura RETURNING id INTO cid; UPDATE public.subcontrato_estados_pago SET estado='Aprobado',monto_aprobado=coalesce(monto_aprobado,monto_presentado),aprobado_por=p_aprobado_por,aprobado_at=now(),costo_real_id=cid WHERE id=ep.id; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) TO authenticated;

;
